import Vue from 'vue';
import { Component, Prop } from 'vue-property-decorator';
import { INicknameState } from '../../types';

@Component({
})
export default class NicknameInput extends Vue {
    @Prop()
    protected translation: string;

    @Prop()
    protected requirement: boolean;

    @Prop()
    protected state: INicknameState;

    get currentLength(): number {
        return this.state.nickname.length;
    }

    constructor() {
        super();
    }
}
